PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, avatar TEXT DEFAULT '🎓', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY AUTOINCREMENT, language TEXT NOT NULL DEFAULT 'ru', question TEXT NOT NULL, answers_json TEXT NOT NULL, correct_index INTEGER NOT NULL, difficulty INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS game_results (id INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT REFERENCES players(id) ON DELETE SET NULL, username TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, prize INTEGER NOT NULL DEFAULT 0, questions_answered INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tournaments (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, title TEXT NOT NULL, host_id TEXT NOT NULL REFERENCES players(id), status TEXT NOT NULL DEFAULT 'waiting', max_players INTEGER NOT NULL DEFAULT 8, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tournament_players (tournament_id TEXT NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE, player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, score INTEGER NOT NULL DEFAULT 0, joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(tournament_id, player_id));
CREATE INDEX IF NOT EXISTS idx_results_score ON game_results(score DESC);
CREATE INDEX IF NOT EXISTS idx_sessions_player ON sessions(player_id);
